import type { JsonSchema } from "../casing/schemaKeyCasing";
import type { OpenApiDocument } from "../spec/loadSpec";
import { resolveRef } from "../spec/resolveRef";

const GENERATED_HEADER = `// Generated by @autumn/atmn-generator from packages/openapi/openapi.yml (the public spec).
// Do not edit — run \`bun generate\` in packages/atmn-generator instead.
`;

/** \`/v1/<group>.<method>\`: the RPC shape; anything else is not a subcommand. */
const RPC_PATH = /^\/v1\/([a-z_]+)\.([a-z_]+)$/;

export type ApiFieldType = "string" | "number" | "boolean" | "json";

export type ApiField = {
	name: string;
	type: ApiFieldType;
	required: boolean;
	description?: string;
};

export type ApiRoute = {
	group: string;
	method: string;
	path: string;
	description?: string;
	/** \`array\` bodies (batch routes) take JSON only; \`none\` takes nothing. */
	body: "object" | "array" | "none";
	fields: ApiField[];
};

const primitiveOf = (type: unknown): ApiFieldType | undefined => {
	if (type === "string") return "string";
	if (type === "number" || type === "integer") return "number";
	if (type === "boolean") return "boolean";
	return undefined;
};

/** A primitive, or a primitive beside null; everything else is typed as JSON. */
const fieldTypeOf = ({
	schema,
	root,
}: {
	schema: JsonSchema;
	root: JsonSchema;
}): ApiFieldType => {
	const resolved = resolveRef({ schema, root }) ?? schema;
	const direct = primitiveOf(resolved.type);
	if (direct) return direct;
	const branches = [...(resolved.anyOf ?? []), ...(resolved.oneOf ?? [])]
		.map((branch) => resolveRef({ schema: branch, root }) ?? branch)
		.filter((branch) => branch.type !== "null");
	if (branches.length === 1 && branches[0]) {
		const only = primitiveOf(branches[0].type);
		if (only) return only;
	}
	return "json";
};

/** The first paragraph, collapsed: help text, not the docs page. */
const summaryOf = (description: unknown): string | undefined => {
	if (typeof description !== "string") return undefined;
	const first = description
		.split(/\n\s*\n/)[0]
		?.replace(/\s+/g, " ")
		.trim();
	return first ? first : undefined;
};

export const apiRoutesOf = ({
	spec,
}: {
	spec: OpenApiDocument;
}): ApiRoute[] => {
	const root = spec as unknown as JsonSchema;
	const routes: ApiRoute[] = [];
	for (const [path, methods] of Object.entries(spec.paths)) {
		const match = RPC_PATH.exec(path);
		const operation = methods.post;
		if (!match || !operation) continue;
		const [, group, method] = match;
		if (group === undefined || method === undefined) continue;
		const raw = operation.requestBody?.content["application/json"]?.schema;
		const schema = raw ? (resolveRef({ schema: raw, root }) ?? raw) : undefined;
		const properties = schema?.properties ?? {};
		const required = new Set(
			Array.isArray(schema?.required) ? (schema.required as string[]) : [],
		);
		const body =
			schema === undefined
				? "none"
				: schema.type === "array"
					? "array"
					: Object.keys(properties).length === 0 && !schema.additionalProperties
						? "none"
						: "object";
		routes.push({
			group,
			method,
			path,
			...(summaryOf(operation.description) === undefined
				? {}
				: { description: summaryOf(operation.description) }),
			body,
			fields: Object.entries(properties).map(([name, property]) => ({
				name,
				type: fieldTypeOf({ schema: property, root }),
				required: required.has(name),
				...(summaryOf(property.description) === undefined
					? {}
					: { description: summaryOf(property.description) }),
			})),
		});
	}
	return routes;
};

/** The header every public operation declares; its default is the version the CLI sends. */
export const apiVersionOf = ({ spec }: { spec: OpenApiDocument }): string => {
	for (const methods of Object.values(spec.paths)) {
		const parameters = methods.post?.parameters ?? [];
		for (const parameter of parameters) {
			if (parameter.in === "header" && parameter.name === "x-api-version") {
				const version = parameter.schema?.default;
				if (typeof version === "string") return version;
			}
		}
	}
	throw new Error("the public spec declares no x-api-version header default");
};

export const emitApiRoutesModule = ({
	spec,
}: {
	spec: OpenApiDocument;
}): string =>
	[
		GENERATED_HEADER,
		`export type ApiFieldType = "string" | "number" | "boolean" | "json";

export type ApiField = {
	readonly name: string;
	readonly type: ApiFieldType;
	readonly required: boolean;
	readonly description?: string;
};

export type ApiRoute = {
	readonly group: string;
	readonly method: string;
	readonly path: string;
	readonly description?: string;
	/** \`array\` bodies (batch routes) take JSON only; \`none\` takes nothing. */
	readonly body: "object" | "array" | "none";
	readonly fields: readonly ApiField[];
};

/** The x-api-version every request carries: the spec's default. */
export const API_VERSION = ${JSON.stringify(apiVersionOf({ spec }))};

export const API_ROUTES: readonly ApiRoute[] = ${JSON.stringify(apiRoutesOf({ spec }), null, "\t")};
`,
	].join("\n");
